<?php require __DIR__.'/../config/functions.php'; require_admin(); $db=get_db(); if(isset($_GET['export'])){ header('Content-Type:text/csv'); header('Content-Disposition:attachment;filename=model_logs.csv'); echo "id,member_id,model_type,cost,status,created_at\n"; foreach($db->query('SELECT * FROM model_logs ORDER BY id DESC') as $r) echo implode(',',array($r['id'],$r['member_id'],$r['model_type'],$r['cost'],$r['status'],$r['created_at']))."\n"; exit;} $where='1=1'; $args=array(); if(!empty($_GET['model_type'])){$where.=' AND model_type=?';$args[]=$_GET['model_type'];} $st=$db->prepare('SELECT * FROM model_logs WHERE '.$where.' ORDER BY id DESC LIMIT 200'); $st->execute($args); page_header('调用日志'); ?><div class="card"><form><select name="model_type"><option value="">全部</option><option>chat</option><option>image</option><option>video</option></select><button>筛选</button><a class="btn" href="?export=1">导出CSV</a></form></div><table><tr><th>时间</th><th>会员</th><th>模型</th><th>消耗</th><th>状态</th><th>摘要</th></tr><?php foreach($st as $r) echo '<tr><td>'.esc($r['created_at']).'</td><td>'.$r['member_id'].'</td><td>'.esc($r['model_type']).'</td><td>'.$r['cost'].'</td><td>'.esc($r['status']).'</td><td>'.esc($r['result_excerpt']).'</td></tr>'; ?></table><?php page_footer(); ?>
